    30  /**
    31   * Width of the bounding box, in rads
    32   * @param  bbox Bounding box to inspect
    33   * @return      width, in rads
    34   */
    35  double bboxWidthRads(const BBox *bbox) {
    36      return bboxIsTransmeridian(bbox) ? bbox->east - bbox->west + M_2PI
    37                                       : bbox->east - bbox->west;
    38  }
    39
    40  /**
    41   * Height of the bounding box
    42   * @param  bbox Bounding box to inspect
    43   * @return      height, in rads
    44   */
    45  double bboxHeightRads(const BBox *bbox) { return bbox->north - bbox->south; }
