    66  /**
    67   * Whether the bounding box contains a given point
    68   * @param  bbox  Bounding box
    69   * @param  point Point to test
    70   * @return       Whether the point is contained
    71   */
    72  bool bboxContains(const BBox *bbox, const LatLng *point) {
    73      return point->lat >= bbox->south && point->lat <= bbox->north &&
    74             (bboxIsTransmeridian(bbox) ?
    75                                        // transmeridian case
    76                  (point->lng >= bbox->west || point->lng <= bbox->east)
    77                                        :
    78                                        // standard case
    79                  (point->lng >= bbox->west && point->lng <= bbox->east));
    80  }
