    82  /**
    83   * Whether two bounding boxes overlap
    84   * @param  a First bounding box
    85   * @param  b Second bounding box
    86   * @return   Whether the bounding boxes overlap
    87   */
    88  bool bboxOverlapsBBox(const BBox *a, const BBox *b) {
    89      // Check whether latitude coords overlap
    90      if (a->north < b->south || a->south > b->north) {
    91          return false;
    92      }
    93
    94      // Check whether longitude coords overlap, accounting for transmeridian
    95      // bboxes
    96      LongitudeNormalization aNormalization;
    97      LongitudeNormalization bNormalization;
    98      bboxNormalization(a, b, &aNormalization, &bNormalization);
    99
   100      if (normalizeLng(a->east, aNormalization) <
   101              normalizeLng(b->west, bNormalization) ||
   102          normalizeLng(a->west, aNormalization) >
   103              normalizeLng(b->east, bNormalization)) {
   104          return false;
   105      }
   106
   107      return true;
   108  }
   109
   110  /**
   111   * Whether one bounding box contains another
   112   * @param  a First bounding box
   113   * @param  b Second bounding box
   114   * @return   Whether a contains b
   115   */
   116  bool bboxContainsBBox(const BBox *a, const BBox *b) {
   117      // Check whether latitude coords are contained
   118      if (a->north < b->north || a->south > b->south) {
   119          return false;
   120      }
   121      // Check whether longitude coords are contained
   122      // Account for transmeridian bboxes
   123      LongitudeNormalization aNormalization;
   124      LongitudeNormalization bNormalization;
   125      bboxNormalization(a, b, &aNormalization, &bNormalization);
   126      return normalizeLng(a->west, aNormalization) <=
   127                 normalizeLng(b->west, bNormalization) &&
   128             normalizeLng(a->east, aNormalization) >=
   129                 normalizeLng(b->east, bNormalization);
   130  }
