    59  /**
    60   * Create a bounding box from a GeoPolygon
    61   * @param polygon Input GeoPolygon
    62   * @param bboxes  Output bboxes, one for the outer loop and one for each hole
    63   */
    64  void bboxesFromGeoPolygon(const GeoPolygon *polygon, BBox *bboxes) {
    65      bboxFromGeoLoop(&polygon->geoloop, &bboxes[0]);
    66      for (int i = 0; i < polygon->numHoles; i++) {
    67          bboxFromGeoLoop(&polygon->holes[i], &bboxes[i + 1]);
    68      }
    69  }
